/// <summary>
/// Updates the AMEX journal number on the <c>CustParameters</c> table.
/// </summary>
/// <param name = "_journalNum"></param>
public static void UpdateAMEXJournalNum(JournalId  _journalNum)
{
    CustParameters  custParameters  = CustParameters::find(true);
    ttsbegin;
    if (_journalnum && custParameters)
    {
        custParameters.METAMEXPaymJournalNum = _journalNum;
        custParameters.doUpdate();
    }
    ttscommit;
}
